const fs = require('fs');
const path = require('path');

const workspace = __dirname;
const manifestPath = path.join(workspace, 'backup-manifest.json');

const entries = fs.readdirSync(workspace, { withFileTypes: true });
const files = entries
  .filter((e) => e.isFile())
  .filter((e) => !e.name.startsWith('.'))
  .filter((e) => e.name !== 'backup-manifest.json')
  .map((e) => e.name)
  .sort();

fs.writeFileSync(manifestPath, JSON.stringify({ files }, null, 2) + '\n');
console.log('wrote manifest with', files);

